/**
 * Northstar Direct Offline File Downloader (js/offline-map.js)
 * - Constrains exported HTML layout inside .app-container (max-width: 480px; margin: 0 auto;)
 * - Embeds REAL stitched OpenStreetMap/Carto street map tiles (Seattle 25-mile radius)
 *   inside .map-card (height: 320px) with numbered pins #1 through #10 matching directory cards
 * - Resets button to "Download" on fresh page load and transitions to "Downloaded ✓" on click
 */

