function getPinBadgeColor(category) {
  const cat = (category || "").toLowerCase();
  if (cat.includes("shelter")) return "#2563eb";
  if (cat.includes("food")) return "#059669";
  return "#d97706";
}

function getBadgeClass(category) {
  const cat = (category || "").toLowerCase();
  if (cat.includes("shelter")) return "badge-shelter";
  if (cat.includes("food")) return "badge-food";
  return "badge-health";
}

// Build a real stitched OpenStreetMap static map image with numbered pin markers #1-#10
function buildRealOpenStreetMapStaticDataUri(resources) {
  const tileCoords = [
    [327, 714, 0, 0],
    [328, 714, 256, 0],
    [329, 714, 512, 0],
    [327, 715, 0, 256],
    [328, 715, 256, 256],
    [329, 715, 512, 256],
    [327, 716, 0, 512],
    [328, 716, 256, 512],
    [329, 716, 512, 512]
  ];

  const tileElements = tileCoords.map(([tx, ty, x, y]) => {
    const key = `${tx}_${ty}`;
    const href = SEATTLE_REAL_TILES_Z11[key] || "";
    return `<image href="${href}" x="${x}" y="${y}" width="256" height="256" preserveAspectRatio="none"/>`;
  }).join("");

  const pinsMarkup = resources.map((item, idx) => {
    const num = idx + 1;
    const x = item.px || 270;
    const y = item.py || 320;
    const fill = getPinBadgeColor(item.category);
    return `
      <g transform="translate(${x}, ${y})">
        <circle r="15" fill="#ffffff" stroke="#0f172a" stroke-width="1.5" opacity="0.95"/>
        <circle r="12" fill="${fill}" stroke="#ffffff" stroke-width="2"/>
        <text y="4" text-anchor="middle" fill="#ffffff" font-family="-apple-system, BlinkMacSystemFont, sans-serif" font-size="11.5" font-weight="900">${num}</text>
      </g>
    `;
  }).join("");

  // Frame the 25-mile Seattle/Bellevue/Renton metro area cleanly inside a 4:3/vertical viewBox
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="145 145 455 475" width="100%" height="100%" preserveAspectRatio="xMidYMid slice">
    <!-- Real OpenStreetMap / Carto Street Tiles -->
    ${tileElements}
    <!-- Subtle 25-Mile Radius Coverage Ring -->
    <circle cx="355" cy="375" r="215" fill="none" stroke="#2563eb" stroke-opacity="0.45" stroke-width="2.5" stroke-dasharray="8,6"/>
    <!-- Numbered Pins #1 through #10 -->
    ${pinsMarkup}
    <!-- Clean Top Attribution / Scale Pill -->
    <rect x="158" y="158" width="248" height="32" rx="8" fill="#0f172a" fill-opacity="0.88"/>
    <text x="170" y="178" fill="#ffffff" font-family="sans-serif" font-size="11" font-weight="800">SEATTLE 25-MILE STREET MAP (PINS #1–#10)</text>
  </svg>`;

  return "data:image/svg+xml;utf8," + encodeURIComponent(svg);
}

function resetButtonToDefaultState() {
  const btn = document.getElementById("download-offline-btn") || document.querySelector("#download-banner button");
  if (!btn) return;
  btn.innerText = "Download";
  btn.classList.remove("download-complete");
  btn.classList.add("download-default");
  btn.style.backgroundColor = "#facc15";
  btn.style.color = "#0f172a";
}

function setButtonDownloadedState(btn) {
  if (!btn) return;
  btn.innerText = "Downloaded ✓";
  btn.classList.remove("download-default");
  btn.classList.add("download-complete");
  btn.style.backgroundColor = "#22c55e";
  btn.style.color = "#ffffff";
}

document.addEventListener("DOMContentLoaded", () => {
  document.getElementById("offline-resources-modal")?.remove();
  document.getElementById("offline-map-directory-modal")?.remove();

  // Default to showing "Download" on initial render
  resetButtonToDefaultState();

  const btn = document.getElementById("download-offline-btn") || document.querySelector("#download-banner button");
  btn?.addEventListener("click", async () => {
    btn.innerText = "Downloading...";

    try {
      let essentials = null;
      const supabaseClient = window.supabaseClient || window.supabase;
      if (supabaseClient && typeof supabaseClient.from === "function") {
        try {
          const { data } = await supabaseClient.from("essentials").select("*");
          if (Array.isArray(data) && data.length > 0) {
            essentials = data;
          }
        } catch (err) {
          console.warn("Supabase query fallback triggered:", err);
        }
      }

      const resources = (essentials && essentials.length >= 6)
        ? essentials.map((item, idx) => ({
            ...item,
            px: REGIONAL_25MI_ESSENTIALS[idx % REGIONAL_25MI_ESSENTIALS.length].px,
            py: REGIONAL_25MI_ESSENTIALS[idx % REGIONAL_25MI_ESSENTIALS.length].py
          }))
        : REGIONAL_25MI_ESSENTIALS;

      const mapDataUri = buildRealOpenStreetMapStaticDataUri(resources);

      const cardsMarkup = resources.map((item, idx) => {
        const badgeClass = getBadgeClass(item.category);
        const hoursText = item.opening_hours || (item.open_24_7 ? "Open 24/7" : "Open Today");
        const cleanPhone = (item.phone || "").replace(/[^0-9+]/g, "");

        return `
      <div class="resource-card">
        <div class="card-header">
          <span class="badge ${badgeClass}">#${idx + 1} · ${item.category || "Essential"}</span>
          <span class="hours">${hoursText}</span>
        </div>
        <div class="resource-title">#${idx + 1} ${item.name}</div>
        <div class="info-line">📍 <span>${item.address}</span></div>
        <div class="info-line">📞 <a class="phone-link" href="tel:${cleanPhone}">${item.phone}</a></div>
      </div>`;
      }).join("\n");

      const offlineHtmlContent = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
  <title>Northstar Offline Directory</title>
  <style>
    * { box-sizing: border-box; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      background-color: #0b0f19;
      color: #f8fafc;
      margin: 0;
      padding: 16px;
      line-height: 1.5;
      display: flex;
      justify-content: center;
    }

    .app-container {
      width: 100%;
      max-width: 480px; /* Constrains desktop view to phone aspect ratio */
      margin: 0 auto;
    }

    .header {
      text-align: center;
      margin-bottom: 16px;
    }
    .header h1 { font-size: 20px; margin: 0 0 4px 0; color: #ffffff; }
    .header p { font-size: 12px; color: #94a3b8; margin: 0; }

    /* Real Static Street Map Container (320px vertical height) */
    .map-card {
      width: 100%;
      height: 320px; /* Gives the map proper vertical height */
      border-radius: 16px;
      overflow: hidden;
      border: 1px solid #334155;
      margin-bottom: 20px;
      background: #1e293b;
    }
    .map-img {
      width: 100%;
      height: 100%;
      object-fit: cover; /* Ensures real map tiles fit without distortion */
      display: block;
    }

    /* Single-Column Mobile Directory Cards */
    .directory-container {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .resource-card {
      background: #151c2c;
      border: 1px solid #283548;
      border-radius: 12px;
      padding: 14px;
    }

    .card-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 6px;
    }

    .badge {
      font-size: 10px;
      font-weight: 700;
      padding: 2px 8px;
      border-radius: 6px;
      text-transform: uppercase;
    }
    .badge-shelter { background: #3b82f6; color: #fff; }
    .badge-food { background: #10b981; color: #fff; }
    .badge-health { background: #f59e0b; color: #fff; }

    .hours {
      font-size: 11px;
      font-weight: 600;
      color: #4ade80;
    }

    .resource-title {
      font-size: 16px;
      font-weight: 700;
      margin: 4px 0;
      color: #ffffff;
    }

    .info-line {
      font-size: 13px;
      color: #cbd5e1;
      margin-top: 4px;
      display: flex;
      align-items: center;
      gap: 6px;
    }

    /* Tap-to-call link for phones */
    .phone-link {
      color: #facc15;
      text-decoration: none;
      font-weight: 600;
    }
  </style>
</head>
<body>
  <div class="app-container">
    <div class="header">
      <h1>Northstar Emergency Directory</h1>
      <p>Offline Regional Map &amp; Verified Resources (25-Mile Radius)</p>
    </div>

    <div class="map-card">
      <img class="map-img" src="${mapDataUri}" onerror="this.src=\"/assets/seattle-25mi-map.png\"" alt="Seattle 25-Mile Street Map">
    </div>

    <div class="directory-container">
${cardsMarkup}
    </div>
  </div>
</body>
</html>`;

      const blob = new Blob([offlineHtmlContent], { type: "text/html;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "Northstar_Offline_Map_Directory.html";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      setButtonDownloadedState(btn);
    } catch (err) {
      console.error("Download error:", err);
      btn.innerText = "Download Failed";
    }
  });
});
